import{_ as d,o as r,c as e,ag as o}from"./chunks/framework.BoXUJ6sC.js";const D=JSON.parse('{"title":"용어","description":"","frontmatter":{},"headers":[],"relativePath":"planning/glossary.md","filePath":"planning/glossary.md"}'),c={name:"planning/glossary.md"};function a(E,t,n,i,l,s){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="용어" tabindex="-1">용어 <a class="header-anchor" href="#용어" aria-label="Permalink to &quot;용어&quot;">​</a></h1><table tabindex="0"><thead><tr><th>한글</th><th>코드 이름 (안)</th><th>뜻</th></tr></thead><tbody><tr><td>자녀 프로필</td><td><code>ChildProfile</code></td><td>보호자 계정 안의 자녀 정보</td></tr><tr><td>성장 이력</td><td><code>GrowthRecord</code></td><td>자녀의 키 · 체형이 바뀔 때마다 쌓는 기록</td></tr><tr><td>배송지</td><td><code>ShippingAddress</code></td><td>회원이 등록한 주소 · 수령인, 배송지가 있으면 기본 배송지는 1개</td></tr><tr><td>판매자</td><td><code>Seller</code></td><td>승인된 판매자 정보 (상호명 · 상태), 판매자 ID = 회원 ID</td></tr><tr><td>옵션</td><td><code>ProductOption</code></td><td>옵션 항목 값(예: 색상 × 사이즈) 한 조합, 재고 단위</td></tr><tr><td>재고 차감 (선점)</td><td><code>deduct</code></td><td>주문 저장 때 판매 가능 수량을 바로 줄임 (나중에 확정하는 단계 없음), 주문 취소 때 복구</td></tr><tr><td>결제대기</td><td><code>PENDING_PAYMENT</code></td><td>주문 저장 직후 상태</td></tr><tr><td>판매자별 주문</td><td><code>SellerOrder</code> (코드: <code>Delivery</code>, API는 sellerOrderId)</td><td>한 주문을 판매자별로 나눈 것, 배송 단위</td></tr><tr><td>주문상품</td><td><code>OrderItem</code></td><td>주문 안의 상품 한 줄, 취소 · 구매확정 · 정산 단위</td></tr><tr><td>구매확정</td><td><code>confirm</code></td><td>이후 취소 · 환불 없음, 정산 대상이 됨</td></tr><tr><td>예치금 · 지갑</td><td><code>Wallet</code></td><td>충전해 두고 결제에 쓰는 돈</td></tr><tr><td>정산 대상</td><td><code>SettlementItem</code> (상태 PENDING · SETTLED · EXCLUDED)</td><td>구매확정된 주문상품 1건. 정산서에 들어가면 그 정산서의 정산 항목</td></tr><tr><td>정산서</td><td>Settlement</td><td>판매자 · 정산 실행(종료일)별 정산 결과 (수수료 · 지급액 · 상태 COMPLETED = 지급 요청 · PAID · FAILED)</td></tr><tr><td>결제 복구</td><td><code>PaymentRecovery</code></td><td>결제 완료를 주문에 반영하지 못한 건. 관리자가 재처리 · 취소하는 처리 대기 목록</td></tr><tr><td>이벤트 처리 실패</td><td><code>OrderEventFailure</code></td><td>주문이 받은 이벤트(재고 차감됨 · 재고 부족함 · 결제 실패됨) 처리에 실패한 건. 처리 대기 목록</td></tr><tr><td>상태 이력</td><td><code>OrderStatusHistory</code></td><td>주문 · 주문상품 · 배송 · 결제 복구의 상태 변경 기록 (누가 · 언제)</td></tr><tr><td>멈춘 주문</td><td><code>StuckOrderKind</code></td><td>기준 시간을 넘겨 다음 단계로 가지 않은 주문의 종류 (조회만)</td></tr><tr><td>정산 실행</td><td>settlementJob</td><td>정산 작업 1회 (자동 · 수동). 기록은 Spring Batch 메타데이터, 응답 상태 RUNNING · COMPLETED · PARTIAL_FAILED · FAILED</td></tr><tr><td>알림</td><td><code>Notification</code></td><td>보낼 메일 한 건 (지금은 가입 환영 메일만)</td></tr><tr><td>상품 유형</td><td><code>ProductType</code></td><td>상품 등록 입력 양식 (의류 · 모자 · 양말). 말단 카테고리마다 하나</td></tr><tr><td>항목</td><td><code>Attribute</code></td><td>상품 유형이 쓰는 입력 칸. 옵션 항목(색상 · 사이즈)과 정보 항목(주요소재 · 혼용률)</td></tr><tr><td>항목 값</td><td><code>AttributeValue</code></td><td>항목에서 고르는 값 (예: 네이비, 110)</td></tr><tr><td>묶음 · 말단 카테고리</td><td><code>Category</code></td><td>묶음 카테고리(의류 · 잡화) 아래 말단 카테고리(상의 · 하의 등). 상품은 말단에만 등록</td></tr><tr><td>사이즈 역할</td><td><code>SIZE</code></td><td>사이즈 항목. 권장 키 · 실측을 사이즈 값마다 받음</td></tr><tr><td>사이즈 무관</td><td><code>sizeFree</code></td><td>사이즈 구분이 없는 상품 (추천은 SIZE_FREE 안내)</td></tr><tr><td>옵션 이름</td><td><code>optionName</code></td><td>옵션 항목 값을 이은 이름 (예: 색상: 네이비 / 사이즈: 110)</td></tr><tr><td>실측 항목</td><td><code>MeasurementItem</code></td><td>총장 · 어깨너비 등 사이즈별로 재는 칸, 카테고리가 필수 항목을 정함</td></tr><tr><td>차감 기록</td><td><code>InventoryDeduction</code></td><td>주문상품마다 재고 차감 결과 (DEDUCTED · RESTORED · FAILED)</td></tr><tr><td>재고 조정 기록</td><td><code>InventoryAdjustmentRecord</code></td><td>판매자 재고 조정 1건 (고치지 않음)</td></tr><tr><td>검색용 표</td><td>ProductSearchDocument</td><td>상품의 되돌리기용 검색 표 (목록 검색은 검색 서비스로 옮김)</td></tr><tr><td>적합도</td><td><code>Fit</code></td><td>ROOMY(여유 있음) · PROPER(적정) · TIGHT(작을 가능성 있음)</td></tr><tr><td>안내 코드</td><td><code>SizeNotice</code></td><td>SIZE_FREE · NO_MATCHING_SIZE · BODY_TYPE_ADJUSTED · PREFERRED_FIT_NOT_APPLIED · HEIGHT_ONLY</td></tr><tr><td>후보 사이즈</td><td><code>candidateSizes</code></td><td>추천 규칙의 후보가 된 사이즈 목록</td></tr><tr><td>지급 요청</td><td>payout</td><td>정산서 금액을 판매자 지갑에 적립해 달라는 요청, 결제가 처리</td></tr><tr><td>영업일 일정산</td><td>-</td><td>주말 · 공휴일을 뺀 날마다 하루 한 번 정산. 공휴일은 특일 정보 API로 판단</td></tr><tr><td>원장</td><td>WalletLedger</td><td>지갑 잔액이 바뀔 때마다 남기는 기록. 종류 CHARGE · CHARGE_CANCEL · CHARGE_CANCEL_REVERT · PAYMENT · REFUND · SETTLEMENT</td></tr><tr><td>지갑 동결</td><td>Wallet.frozenAt</td><td>탈퇴한 회원의 지갑에서 돈이 나가는 요청을 막은 상태. 잔액 · 입금은 그대로</td></tr><tr><td>충전</td><td>Charge</td><td>토스로 예치금을 넣는 요청. 상태 PENDING · CONFIRMING(승인 중) · DONE · CANCELLING · CANCELLED · FAILED · EXPIRED</td></tr><tr><td>결제</td><td>Payment</td><td>주문 한 건의 예치금 결제. 상태 COMPLETED · FAILED · PARTIALLY_REFUNDED · REFUNDED</td></tr><tr><td>환불</td><td>Refund · RefundItem</td><td>주문 전체 취소(결제당 한 번) 또는 판매자 부분 취소(취소당 한 번)의 예치금 환불과 주문상품별 금액</td></tr><tr><td>지급</td><td>Payout</td><td>정산서 한 건의 판매자 지갑 입금 결과(COMPLETED · FAILED). 정산서 ID당 하나</td></tr><tr><td>취소된 주문 기록</td><td>CancelledOrder</td><td>결제 전에 취소된 주문. 뒤늦게 온 결제 요청을 차감하지 않으려고 남김</td></tr><tr><td>아웃박스</td><td>PaymentOutboxMessage</td><td>보낼 이벤트를 업무와 같은 트랜잭션에 저장한 표. 릴레이가 Kafka로 보내고 보낸 시각을 남김</td></tr><tr><td>DLT</td><td>{토픽}.{받는도메인}.dlt</td><td>받는 쪽이 여러 번 시도해도 처리하지 못한 메시지를 모아 두는 토픽</td></tr><tr><td>수신 스위치</td><td>kidly.{도메인}.kafka.consumer.enabled</td><td>Kafka로 받을지 Spring 이벤트로 받을지 고르는 설정값. 장애 때 되돌리는 데 씀</td></tr><tr><td>검색 문서</td><td>SearchProduct</td><td>product.changed 하나로 만든 Elasticsearch 상품 문서(표시 가격 · 품절 · 항목 값)</td></tr><tr><td>검색 판매자</td><td>SearchSeller</td><td>상호명만 담은 판매자 문서. 판매자가 바뀌어도 상품 문서를 고치지 않으려고 따로 둠</td></tr><tr><td>처음 채우기</td><td>-</td><td>새로 만든 색인이 비어 있어, 상품 · 판매자가 전체를 이벤트로 다시 보내 채우는 것</td></tr><tr><td>형태소 분석</td><td>nori</td><td>한글 검색어를 뜻 단위로 나눠, 띄어쓰기 · 조사 · 어순이 달라도 찾게 하는 Elasticsearch 분석기</td></tr><tr><td>활동 기록</td><td>ActivityRecord</td><td>추천이 받는 사용자 행동 4종(상세 진입 · 검색어 · 장바구니 담기와 빼기 · 구매자 취소)의 저장 단위</td></tr><tr><td>선호 점수</td><td>ChildPreference</td><td>활동 기록으로 자녀마다 카테고리 · 브랜드에 매긴 점수. 더보기 목록 정렬과 AI 후보 선정에 씀</td></tr><tr><td>후보</td><td>candidates</td><td>AI에게 주는 고를 수 있는 목록. 사이즈는 상품의 실제 사이즈, 상품은 규칙과 벡터로 거른 20개</td></tr><tr><td>출처</td><td>source</td><td>응답을 AI가 만들었는지(AI) 규칙으로 대신했는지(RULE)</td></tr><tr><td>임베딩</td><td>embedding</td><td>상품 글을 숫자 벡터로 바꾼 값. 뜻이 비슷한 상품끼리 가까운 값이 됨</td></tr><tr><td>벡터 저장소</td><td>vector store</td><td>임베딩을 저장하고 가까운 순으로 찾는 저장소</td></tr><tr><td>AI 응답 저장</td><td>RecommendationResponse</td><td>입력 해시를 키로 AI 응답을 저장한 표. 같은 입력이면 재사용하고, 입력 스냅샷 로그를 겸함</td></tr><tr><td>기준 옷</td><td>ReferenceGarment</td><td>자녀가 지금 잘 맞게 입는 옷. 자녀마다 상의 · 하의 한 벌씩, 실측을 cm로 저장(2순위)</td></tr><tr><td>기준 핏</td><td>-</td><td>기준 옷의 실측과 상품 실측의 차이(예: 가슴 +2cm)(2순위)</td></tr><tr><td>상품 실측</td><td>SizeSpec.measurements</td><td>판매자가 사이즈마다 적은 옷 치수(세미에 이미 있음)</td></tr><tr><td>공용 장바구니</td><td>Wish (주문 wish 컨텍스트)</td><td>부모 · 자녀가 같이 보는 자녀별 장바구니. 개인 장바구니와 별도</td></tr><tr><td>조르기</td><td>WishRequest</td><td>자녀가 공용 장바구니 상품을 보내 부모의 승인 · 거절을 받는 요청</td></tr><tr><td>판매자 부분 취소</td><td>order-item.cancelled · cancellationId</td><td>판매자가 발송 전 자기 몫(배송 한 건)을 취소한 것. 취소마다 ID가 있어 환불 · 재고 복구가 한 번만 일어남</td></tr><tr><td>리뷰</td><td>Review</td><td>구매확정한 주문상품에 남기는 별점(1~5)과 본문. 주문상품마다 1개</td></tr><tr><td>작성 자격</td><td>ReviewEligibility</td><td>리뷰를 쓸 수 있는 주문상품. 구매확정 이벤트로 만든다</td></tr><tr><td>찜</td><td>favorite</td><td>회원이 관심 상품을 표시해 둔 것. 회원 × 상품마다 1개 (조르기와 다름)</td></tr><tr><td>표시 상태</td><td>displayStatus</td><td>ON_SALE(판매 중) · SOLD_OUT(품절) · SALE_ENDED(판매 종료). 커뮤니티 화면용</td></tr></tbody></table>',2)])])}const A=d(c,[["render",a]]);export{D as __pageData,A as default};
